-- ═══════════════════════════════════════════════════════════════════
-- Idempotent civics re-match fix. Only touches the אזרחות rows of
-- student_subject_progress + fills missing national_id. Does NOT delete
-- students, does NOT re-run the main backfill, does NOT touch bagrut_data.
-- Matching order: national_id -> exact name+class -> normalized name +
-- normalized grade (strip digits/spaces) -> explicit name map.
-- ═══════════════════════════════════════════════════════════════════
CREATE TEMP TABLE _map (civics_name text, roster_name text);
INSERT INTO _map VALUES
  ('חרמצקי איתן אפרים', 'חרמצקי איתן'),
  ('נאור אביתר יצחק', 'נאור אביתר'),
  ('נעם עידו יעקב', 'נעם עידו'),
  ('קוראין משב אלי', 'קוראין משב'),
  ('שעשוע חנוך אליעזר', 'שעשוע חנוך'),
  ('ווגאיו עידן', 'ווגיאו עידן'),
  ('ימין ריף יהלי', 'ריף ימין'),
  ('ריזלמן-לוקסן עדן', 'רייזלמן עדן'),
  ('תירוש תומר', 'תירוש תומר');

CREATE TEMP TABLE _civ AS
SELECT e->>'n' AS name, e->>'id' AS nid, e->>'c' AS cls,
       CASE WHEN e->>'grade' ~ '^[0-9.]+$' THEN (e->>'grade')::numeric ELSE NULL END AS grade,
       e->'details' AS details, NULL::uuid AS student_id
