-- 1. national_id
UPDATE _civ c SET student_id = s.id FROM public.students s
  WHERE c.nid IS NOT NULL AND c.nid <> '' AND s.national_id = c.nid;

-- 2. exact name + class
UPDATE _civ c SET student_id = s.id FROM public.students s
  WHERE c.student_id IS NULL AND s.full_name = c.name AND s.class_name = c.cls;

-- 3. normalized name + normalized grade (strip digits/spaces from class)
UPDATE _civ c SET student_id = s.id FROM public.students s
  WHERE c.student_id IS NULL
    AND regexp_replace(s.full_name, '\s+', ' ', 'g') = regexp_replace(c.name, '\s+', ' ', 'g')
    AND regexp_replace(s.class_name, '[0-9 ]', '', 'g') = regexp_replace(c.cls, '[0-9 ]', '', 'g');

-- 4. explicit name map -> roster full_name (unique)
UPDATE _civ c SET student_id = s.id
  FROM _map m JOIN public.students s ON s.full_name = m.roster_name
  WHERE c.student_id IS NULL AND c.name = m.civics_name;

-- 4b. Create רותם גיל as a new student if still unmatched (idempotent; id from the civics file; sport unknown)
DO $$
DECLARE v_nid text; v_sid uuid;
BEGIN
  SELECT nid INTO v_nid FROM _civ WHERE name = 'רותם גיל' AND student_id IS NULL LIMIT 1;
  IF FOUND THEN
    SELECT id INTO v_sid FROM public.students
     WHERE (v_nid IS NOT NULL AND v_nid <> '' AND national_id = v_nid)
        OR (full_name = 'רותם גיל' AND class_name = 'יא1')
     LIMIT 1;
    IF v_sid IS NULL THEN
      INSERT INTO public.students (full_name, class_name, sport, national_id)
      VALUES ('רותם גיל', 'יא1', 'לא צוין', NULLIF(v_nid, ''))
      RETURNING id INTO v_sid;
    END IF;
    UPDATE _civ SET student_id = v_sid WHERE name = 'רותם גיל';
  END IF;
END $$;

DO $$ DECLARE mt int; un int; unl text;
BEGIN
  SELECT count(*) FILTER (WHERE student_id IS NOT NULL),
         count(*) FILTER (WHERE student_id IS NULL) INTO mt, un FROM _civ;
  SELECT string_agg(name, ', ') INTO unl FROM _civ WHERE student_id IS NULL;
  RAISE NOTICE 'CIVICS matched=%, unmatched=%, unmatched_names=[%]', mt, un, COALESCE(unl,'none');
END $$;

-- 5. fill missing national_id from civics (only where currently empty)
UPDATE public.students s SET national_id = c.nid
  FROM _civ c
  WHERE c.student_id = s.id AND c.nid IS NOT NULL AND c.nid <> ''
    AND (s.national_id IS NULL OR s.national_id = '');

-- 6. upsert only the אזרחות rows
INSERT INTO public.student_subject_progress (student_id, subject_id, grade, details)
SELECT DISTINCT ON (c.student_id) c.student_id,
       (SELECT id FROM public.subjects WHERE subject_name = 'אזרחות'), c.grade, c.details
FROM _civ c WHERE c.student_id IS NOT NULL
ORDER BY c.student_id
ON CONFLICT (student_id, subject_id) DO UPDATE SET grade = EXCLUDED.grade, details = EXCLUDED.details;

DO $$ DECLARE p int; b int; st int;
BEGIN
  SELECT count(*) INTO st FROM public.students;
  SELECT count(*) INTO b FROM public.student_bagrut_data;
  SELECT count(*) INTO p FROM public.student_subject_progress;
  RAISE NOTICE 'students=%, student_bagrut_data=%, progress_total=%', st, b, p;
END $$;

DROP TABLE _map; DROP TABLE _civ;